import csv
from collections import defaultdict

def sums(path):
    totals=defaultdict(float)
    with open(path,newline='') as f:
        r=csv.DictReader(f)
        for row in r:
            for k,v in row.items():
                if k=='vendor' or k=='comments' or k=='account_number':
                    continue
                if v is None or v=='':
                    continue
                try:
                    totals[k]+=float(v)
                except ValueError:
                    pass
    return totals

for name,path in [('bus','/root/bus_pass_schedule_input.csv'),('rail','/root/rail_pass_schedule_input.csv')]:
    t=sums(path)
    print(name,'rows totals for select fields:')
    for k in ['beginning_balance','jan_adds','jan_amortization','jan_ending_balance','feb_adds','feb_amortization','feb_ending_balance','mar_adds','mar_amortization','mar_ending_balance','apr_adds','apr_amortization','apr_ending_balance']:
        print(' ',k,round(t[k],2))
    print('')
PY

